package de.ostms.lc.lc.api;
import de.ostms.lc.audit.service.AuditService;import de.ostms.lc.lc.domain.LcTask;import de.ostms.lc.lc.service.LcTaskService;import de.ostms.lc.user.service.UserService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class LcTaskController {private final LcTaskService service;private final UserService users;private final AuditService audit;public LcTaskController(LcTaskService s,UserService u,AuditService a){service=s;users=u;audit=a;}@GetMapping("/api/tasks/open")public List<LcTask> open(){return service.open();}@GetMapping("/api/lcs/{lcId}/tasks")public List<LcTask> forLc(@PathVariable UUID lcId){return service.forLc(lcId);}@PostMapping("/api/lcs/{lcId}/tasks")public LcTask create(@PathVariable UUID lcId,@Valid @RequestBody LcTaskRequest request,Authentication auth){if(request.assignedTo()!=null&&!request.assignedTo().isBlank()&&!users.isAssignable(request.assignedTo()))throw new IllegalArgumentException("Der ausgewählte Bearbeiter ist nicht aktiv.");LcTask task=service.create(lcId,request,auth.getName());audit.record(auth,"LC_TASK_CREATED","LETTER_OF_CREDIT",lcId,task.getTitle());return task;}@PutMapping("/api/lcs/{lcId}/tasks/{taskId}/complete")public LcTask complete(@PathVariable UUID lcId,@PathVariable UUID taskId,@RequestParam boolean completed,Authentication auth){LcTask task=service.complete(lcId,taskId,completed);audit.record(auth,completed?"LC_TASK_COMPLETED":"LC_TASK_REOPENED","LETTER_OF_CREDIT",lcId,task.getTitle());return task;}@DeleteMapping("/api/lcs/{lcId}/tasks/{taskId}")public ResponseEntity<Void> delete(@PathVariable UUID lcId,@PathVariable UUID taskId,Authentication auth){service.delete(lcId,taskId);audit.record(auth,"LC_TASK_DELETED","LETTER_OF_CREDIT",lcId,"Aufgabe gelöscht");return ResponseEntity.noContent().build();}}
